/**
 * The exit code surfaced to the OS scheduler. Mapped from {@link TaskRunStatus}
 * so cron / launchd / schtasks see a useful return value.
 */
export function exitCodeForStatus(status) {
    switch (status) {
        case "completed":
            return 0;
        case "active":
            return 0;
        case "blocked":
            return 1;
        case "failed":
            return 1;
    }
}
